import React, { useState } from "react";
import api from "@/services/api";
import { FaHeart, FaRegHeart, FaEdit, FaSave, FaTimes } from "react-icons/fa";
import CommentSection from "./CommentSection";
import { useAuth } from "@/contexts/AuthContext";

const PostCard = ({ post }) => {
  const { user } = useAuth();
  const {
    id,
    imageUrl,
    caption: originalCaption,
    tags: originalTags,
    createdBy,
    likedByUser,
    likeCount,
  } = post;

  const [liked, setLiked] = useState(!!likedByUser);
  const [likes, setLikes] = useState(likeCount || 0);

  const [editing, setEditing] = useState(false);
  const [caption, setCaption] = useState(originalCaption);
  const [tags, setTags] = useState(originalTags.join(", "));

  const toggleLike = async () => {
    try {
      const res = await api.post(`/posts/${id}/like`);
      setLiked(res.data.liked);
      setLikes(res.data.likes);
    } catch (err) {
      console.error("Error toggling like:", err);
    }
  };

  const handleSave = async () => {
    try {
      const tagArray = tags
        .split(",")
        .map((t) => t.trim())
        .filter(Boolean);
      const res = await api.put(`/posts/${id}`, {
        caption,
        tags: tagArray,
      });
      setCaption(res.data.caption);
      setTags(res.data.tags.join(", "));
      setEditing(false);
    } catch (err) {
      console.error("Failed to update post:", err);
    }
  };

  const isOwner = user?.id === createdBy?.id;

  return (
    <div className="bg-white shadow-md rounded-lg overflow-hidden">
      <img src={imageUrl} alt="post" className="w-full h-64 object-cover" />
      <div className="p-4">
        <div className="font-semibold mb-2 text-neutral-800">
          @{createdBy?.username || "Unknown"}
        </div>

        {editing ? (
          <>
            <textarea
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
              className="w-full border rounded p-2 mb-2"
            />
            <input
              type="text"
              value={tags}
              onChange={(e) => setTags(e.target.value)}
              className="w-full border rounded p-2 mb-2"
              placeholder="Comma separated tags"
            />
            <div className="flex gap-2 mb-2">
              <button onClick={handleSave} className="text-green-600">
                <FaSave /> Save
              </button>
              <button
                onClick={() => setEditing(false)}
                className="text-red-600"
              >
                <FaTimes /> Cancel
              </button>
            </div>
          </>
        ) : (
          <>
            <p className="text-gray-800 mb-2">
              {caption.replace(/#[\w_]+/g, "").trim()}
            </p>

            <div className="flex flex-wrap gap-2 mb-2">
              {originalTags?.map((tag, i) => (
                <span
                  key={i}
                  className="bg-blue-100 text-blue-800 px-2 py-1 text-xs rounded-full"
                >
                  #{tag}
                </span>
              ))}
            </div>

            {isOwner && (
              <button
                onClick={() => setEditing(true)}
                className="text-sm text-blue-600 mb-2 flex items-center gap-1"
              >
                <FaEdit /> Edit
              </button>
            )}
          </>
        )}

        <div className="flex items-center gap-2 text-sm text-gray-600 mb-2">
          <button onClick={toggleLike}>
            {liked ? <FaHeart className="text-red-500" /> : <FaRegHeart />}
          </button>
          {likes} likes
        </div>

        <CommentSection postId={id} />
      </div>
    </div>
  );
};

export default PostCard;
